/**
 * Recognises an org's check-in QR code and pulls out the org slug.
 *
 * Officers display a QR code generated by the web app. The link format is
 * defined in one place, web's lib/checkin-link.ts (buildCheckinLink), as
 * "<origin>/<encodeURIComponent(slug)>/checkin". That file is the source of
 * truth: if it changes, this parser must change with it.
 *
 * Returns null for anything else (plain text, other apps' links, Wi-Fi codes),
 * so the scanner can say "not a check-in code" instead of guessing.
 */

export function parseCheckinLink(data: string): string | null {
  let url: URL;
  try {
    url = new URL(data.trim());
  } catch {
    return null;
  }
  if (url.protocol !== 'http:' && url.protocol !== 'https:') return null;

  // Any host is accepted: prod, localhost and LAN IPs (local dev) all produce
  // valid codes. The host isn't trusted for anything -- the app checks in
  // against its own backend, which validates the org slug itself.

  // Exactly "/<slug>/checkin", optionally with one trailing slash. Query and
  // hash are ignored.
  const match = /^\/([^/]+)\/checkin\/?$/.exec(url.pathname);
  if (!match) return null;

  let slug: string;
  try {
    slug = decodeURIComponent(match[1]);
  } catch {
    return null;
  }
  if (slug.length === 0 || slug.includes('/')) return null;

  // Return the slug exactly as encoded. The web builds the QR from the stored
  // slug and looks orgs up case-sensitively (.eq("slug", ...)), so changing
  // case here could miss older orgs whose slugs were never normalised (see
  // 20260820010000_organizations_slug_unique.sql).
  return slug;
}
